int32_t pseudomersenne_reduce_single_n1087(int32_t a)
{
    int32_t t0, t1;
    t0 = a & 0xffffff;
    t1 = a >> 24;
    t0 = (t1 << 8) + t0 - t1 - Q_N1087;
    return t0;
}

int32_t montgomery_reduce_n1087(int64_t a)
{
    int32_t t;
    t = (int32_t)a * QINV_N1087;
    t = (a - (int64_t)t * Q_N1087) >> 32;
    return t;
}

int32_t fqmul_n1087(int32_t a, int32_t b)
{
    return montgomery_reduce_n1087((int64_t)a * b);
}

void ntt(int32_t a[N_N1087])
{
    unsigned int len, start, j, k = 0;
    int32_t zeta, t, z[3];

    len = N_N1087 / 3;
    for (start = 0; start < N_N1087; start += 3 * len)
    {
        zeta = zetas[k++];
        for (j = start; j < start + len; ++j)
        {
            z[0] = a[j + len];
            z[1] = a[j + 2 * len];
            z[2] = fqmul_n1087(z[0] - z[1], zeta);
            a[j + len] = a[j] - z[0] - z[2];
            a[j + 2 * len] = a[j] + z[0] + z[1];
            a[j] = a[j] - z[1] + z[2];
        }
    }

    for (len = N_N1087 / 6; len >= 3; len >>= 1)
    {
        for (start = 0; start < N_N1087; start = j + len)
        {
            zeta = zetas[k++];
            for (j = start; j < start + len; ++j)
            {
                t = fqmul_n1087(zeta, a[j + len]);
                a[j + len] = (a[j] - t);
                a[j] = (a[j] + t);
            }
        }
    }
}

